def model(key,carbons,c_bonds,hydrogens,label):
    defs=f'<defs><radialGradient id="{key}-c" cx="35%" cy="28%"><stop stop-color="#726666"/><stop offset="1" stop-color="#2b2124"/></radialGradient><radialGradient id="{key}-h" cx="30%" cy="25%"><stop stop-color="#ffffff"/><stop offset="1" stop-color="#b8b8a7"/></radialGradient></defs>'
    bonds=[]
    for i,j in c_bonds:
        x,y=carbons[i];u,v=carbons[j]
        bonds.append(f'<path d="M{x} {y}L{u} {v}" stroke="#887077" stroke-width="5"/>')
    for parent,x,y in hydrogens:
        u,v=carbons[parent]
        bonds.append(f'<path d="M{u} {v}L{x} {y}" stroke="#a28e92" stroke-width="5"/>')
    atom_c=''.join(f'<circle cx="{x}" cy="{y}" r="17" fill="url(#{key}-c)"/>' for x,y in carbons)
    atom_h=''.join(f'<circle cx="{x}" cy="{y}" r="10" fill="url(#{key}-h)"/>' for _,x,y in hydrogens)
    return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 350 258" role="img" aria-label="{label}: four carbon atoms and ten hydrogen atoms" style="max-width:520px;width:100%;height:auto">'+defs+''.join(bonds)+atom_c+atom_h+f'<text x="175" y="243" text-anchor="middle" font-family="Arial,sans-serif" font-size="16" fill="#29202a">{label}</text></svg>'
